import Mathlib

namespace Submission

/-
Over an algebraically closed field, the trace of a linear map equals
    the sum of the roots of its characteristic polynomial.
-/
lemma trace_eq_sum_charpoly_roots {K V : Type*} [Field K] [IsAlgClosed K]
    [AddCommGroup V] [Module K V] [FiniteDimensional K V]
    (f : V →ₗ[K] V) :
    (LinearMap.trace K V) f = f.charpoly.roots.sum := by
  convert Matrix.trace_eq_sum_roots_charpoly _;
  · exact?;
  · infer_instance

/-
If `f ^ n = 1` (as a linear map), then every root of `f.charpoly` satisfies `μ ^ n = 1`.
-/
lemma charpoly_root_pow_eq_one {K V : Type*} [Field K] [IsAlgClosed K]
    [AddCommGroup V] [Module K V] [FiniteDimensional K V]
    (f : V →ₗ[K] V) (n : ℕ) (hf : f ^ n = 1) (μ : K) (hμ : μ ∈ f.charpoly.roots) :
    μ ^ n = 1 := by
  -- Since μ is an eigenvalue of f, there exists a nonzero vector v such that f v = μ • v.
  obtain ⟨v, hv⟩ : ∃ v : V, v ≠ 0 ∧ f v = μ • v := by
    have h_eigenvalue : ∃ v : V, v ≠ 0 ∧ f v = μ • v := by
      have h_eigenvalue_def : ∃ v : V, v ≠ 0 ∧ (f - μ • 1) v = 0 := by
        have h_eigenvalue_def : LinearMap.det (f - μ • 1) = 0 := by
          rw [ LinearMap.det_eq_sign_charpoly_coeff ];
          simp_all +decide [ LinearMap.charpoly, Matrix.charpoly ];
          convert hμ.2 using 1;
          simp +decide [ Matrix.det_apply', Polynomial.eval_finset_sum ];
          simp +decide [ Polynomial.coeff_zero_eq_eval_zero, Polynomial.eval_prod ];
          exact Finset.sum_congr rfl fun _ _ => by congr; ext; by_cases h : ‹Equiv.Perm ( Module.Free.ChooseBasisIndex K V ) › ‹_› = ‹_› <;> simp +decide [ h ] ;
        have := LinearMap.isUnit_det ( f - μ • 1 );
        simp_all +decide [ LinearMap.isUnit_iff_ker_eq_bot ];
        simp_all +decide [ Submodule.eq_bot_iff ];
        tauto
      simp_all +decide [ sub_eq_zero ];
    exact h_eigenvalue;
  -- Since $f^n = id$, we have $f^n(v) = v$ for any vector $v$.
  have h_fn : f^[n] v = v := by
    convert congr_arg ( fun g : V →ₗ[K] V => g v ) hf;
    exact?;
  -- Since $f(v) = μ • v$, we have $f^n(v) = μ^n • v$.
  have h_fn_v : f^[n] v = μ^n • v := by
    refine' Nat.recOn n _ _ <;> simp_all +decide [ pow_succ', Function.iterate_succ_apply', smul_smul ];
    exact fun _ _ => mul_comm _ _;
  exact smul_left_injective _ hv.1 ( by aesop )

/-
Every `n`-th root of unity in `ℂ` lies in the range of any `ℚ`-algebra map from
    `CyclotomicField n ℚ` into `ℂ`, provided `n ≠ 0`.
-/
lemma root_of_unity_mem_cyclotomic_range
    (n : ℕ) (hn : n ≠ 0)
    (φ : CyclotomicField n ℚ →ₐ[ℚ] ℂ)
    (ω : ℂ) (hω : ω ^ n = 1) :
    ω ∈ φ.toRingHom.range := by
  -- Since $\zeta$ is a primitive $n$-th root of unity, the set $\{ \zeta^k \mid k = 0, 1, 2, \ldots, n-1 \}$ is precisely the set of $n$-th roots of unity.
  obtain ⟨ζ, hζ⟩ : ∃ ζ : CyclotomicField n ℚ, IsPrimitiveRoot ζ n := by
    have h_cyclotomic : IsCyclotomicExtension {n} ℚ (CyclotomicField n ℚ) := by
      exact CyclotomicField.instIsCyclotomicExtensionSingletonNatSetOfCharZero n ℚ
    have := h_cyclotomic;
    cases this ; aesop
  have h_roots_of_unity : ∀ ω : ℂ, ω ^ n = 1 → ∃ k : Fin n, ω = (φ ζ) ^ (k : ℕ) := by
    intro ω hω
    have h_roots_of_unity : Finset.image (fun k : Fin n => (φ ζ) ^ (k : ℕ)) (Finset.univ : Finset (Fin n)) = Multiset.toFinset (Polynomial.roots (Polynomial.X ^ n - 1 : Polynomial ℂ)) := by
      refine' Finset.eq_of_subset_of_card_le ( _ ) _;
      · simp_all +decide [ Finset.subset_iff ];
        exact fun a => ⟨ ne_of_apply_ne ( Polynomial.eval 0 ) ( by norm_num [ hn ] ), by rw [ ← pow_mul, Nat.mul_comm, pow_mul, show φ ζ ^ n = 1 from by simpa [ ← map_pow ] using congr_arg ( φ ) ( hζ.pow_eq_one ) ] ; norm_num ⟩;
      · rw [ Finset.card_image_of_injective _ fun a b h => _ ];
        · exact le_trans ( Multiset.toFinset_card_le _ ) ( le_trans ( Polynomial.card_roots' _ ) ( by erw [ Polynomial.natDegree_X_pow_sub_C ] ; simpa ) );
        · intro a b hab; have := hζ.pow_inj ( Fin.is_lt a ) ( Fin.is_lt b ) ; simp_all +decide [ ← map_pow ] ;
          exact Fin.ext ( this <| by simpa [ hn ] using φ.injective hab );
    replace h_roots_of_unity := Finset.ext_iff.mp h_roots_of_unity ω; simp_all +decide [ sub_eq_iff_eq_add ] ;
    exact h_roots_of_unity.mpr ( ne_of_apply_ne Polynomial.natDegree <| by aesop ) |> fun ⟨ k, hk ⟩ => ⟨ k, hk.symm ⟩;
  obtain ⟨ k, rfl ⟩ := h_roots_of_unity ω hω; exact ⟨ ζ ^ ( k : ℕ ), by simp +decide ⟩ ;

theorem brauer_character_in_cyclotomic (G : Type) [Group G] [Fintype G] :
    ∃ φ : CyclotomicField (Monoid.exponent G) ℚ →+* ℂ,
      ∀ (V : Type) (_ : AddCommGroup V) (_ : Module ℂ V) (_ : FiniteDimensional ℂ V)
        (ρ : Representation ℂ G V) (g : G),
        LinearMap.trace ℂ V (ρ g) ∈ φ.range := by
  constructor;
  intro V _ _ _ ρ g;
  have h_trace : (LinearMap.trace ℂ V) (ρ g) = (ρ g).charpoly.roots.sum := by
    convert trace_eq_sum_charpoly_roots ( ρ g ) using 1;
  have h_roots : ∀ μ ∈ (ρ g).charpoly.roots, μ ^ Monoid.exponent G = 1 := by
    apply charpoly_root_pow_eq_one;
    simp +decide [ ← map_pow, Monoid.pow_exponent_eq_one ];
  have h_roots_mem : ∀ μ ∈ (ρ g).charpoly.roots, μ ∈ (IsAlgClosed.lift : CyclotomicField (Monoid.exponent G) ℚ →ₐ[ℚ] ℂ).toRingHom.range := by
    by_cases h : Monoid.exponent G = 0;
    · exact absurd h ( Monoid.exponent_ne_zero_of_finite );
    · exact?;
  convert Subring.multiset_sum_mem _ _ _;
  exacts [ h_trace, h_roots_mem ]

end Submission

import Mathlib

namespace Submission

theorem bvp_comparison (J : Set ℝ) (hJ_open : IsOpen J) (hJ_sub : Set.Icc (0 : ℝ) 1 ⊆ J)
    (u v : ℝ → ℝ)
    (hu : ∀ x ∈ J, HasDerivAt u (deriv u x) x)
    (hu' : ∀ x ∈ J, HasDerivAt (deriv u) (deriv (deriv u) x) x)
    (hv : ∀ x ∈ J, HasDerivAt v (deriv v x) x)
    (hv' : ∀ x ∈ J, HasDerivAt (deriv v) (deriv (deriv v) x) x)
    (hineq : ∀ x ∈ Set.Ioo (0 : ℝ) 1, -deriv (deriv u) x ≤ -deriv (deriv v) x)
    (hu0 : u 0 ≤ v 0) (hu1 : u 1 ≤ v 1) :
    ∀ x ∈ Set.Icc (0 : ℝ) 1, u x ≤ v x := by
  -- Define $w(x) = u(x) - v(x)$.
  set w : ℝ → ℝ := fun x => u x - v x;
  -- By definition of $w$, we know that $w''(x) \geq 0$ for all $x \in (0,1)$.
  have hw''_nonneg : ∀ x ∈ Set.Ioo 0 1, deriv^[2] w x ≥ 0 := by
    simp +zetaDelta at *;
    intro x hx₁ hx₂; rw [ show deriv ( deriv fun x => u x - v x ) x = deriv ( fun x => deriv u x - deriv v x ) x from Filter.EventuallyEq.deriv_eq <| Filter.eventuallyEq_of_mem ( Ioo_mem_nhds hx₁ hx₂ ) fun y hy => deriv_sub ( hu y <| hJ_sub <| Set.Ioo_subset_Icc_self hy ) ( hv y <| hJ_sub <| Set.Ioo_subset_Icc_self hy ) ] ;
    norm_num [ hu' x ( hJ_sub <| Set.mem_Icc.mpr ⟨ hx₁.le, hx₂.le ⟩ ), hv' x ( hJ_sub <| Set.mem_Icc.mpr ⟨ hx₁.le, hx₂.le ⟩ ) ] ; linarith [ hineq x hx₁ hx₂ ];
  -- Since $w''(x) \geq 0$ for all $x \in (0,1)$, $w$ is convex on $[0,1]$.
  have hw_convex : ConvexOn ℝ (Set.Icc 0 1) w := by
    apply_rules [ convexOn_of_deriv2_nonneg, convex_Icc ];
    · exact ContinuousOn.sub ( continuousOn_of_forall_continuousAt fun x hx => HasDerivAt.continuousAt ( hu x ( hJ_sub hx ) ) ) ( continuousOn_of_forall_continuousAt fun x hx => HasDerivAt.continuousAt ( hv x ( hJ_sub hx ) ) );
    · exact fun x hx => DifferentiableAt.differentiableWithinAt ( by exact DifferentiableAt.sub ( hu x ( hJ_sub <| interior_subset hx ) |> HasDerivAt.differentiableAt ) ( hv x ( hJ_sub <| interior_subset hx ) |> HasDerivAt.differentiableAt ) );
    · norm_num +zetaDelta at *;
      refine' DifferentiableOn.congr _ _;
      exacts [ fun x => deriv u x - deriv v x, fun x hx => DifferentiableAt.differentiableWithinAt ( by exact DifferentiableAt.sub ( hu' x ( hJ_sub <| Set.Ioo_subset_Icc_self hx ) ) ( hv' x ( hJ_sub <| Set.Ioo_subset_Icc_self hx ) ) ), fun x hx => deriv_sub ( hu x ( hJ_sub <| Set.Ioo_subset_Icc_self hx ) ) ( hv x ( hJ_sub <| Set.Ioo_subset_Icc_self hx ) ) ];
    · aesop;
  intro x hx;
  have := hw_convex.2 ( show 0 ∈ Set.Icc 0 1 by norm_num ) ( show 1 ∈ Set.Icc 0 1 by norm_num );
  simp +zetaDelta at *;
  nlinarith [ this ( show 0 ≤ 1 - x by linarith ) ( show 0 ≤ x by linarith ) ( by linarith ) ]

end Submission

import Mathlib

namespace Submission

theorem bvp_comparison (J : Set ℝ) (hJ_open : IsOpen J) (hJ_sub : Set.Icc (0 : ℝ) 1 ⊆ J)
    (u v : ℝ → ℝ)
    (hu : ∀ x ∈ J, HasDerivAt u (deriv u x) x)
    (hu' : ∀ x ∈ J, HasDerivAt (deriv u) (deriv (deriv u) x) x)
    (hv : ∀ x ∈ J, HasDerivAt v (deriv v x) x)
    (hv' : ∀ x ∈ J, HasDerivAt (deriv v) (deriv (deriv v) x) x)
    (hineq : ∀ x ∈ Set.Ioo (0 : ℝ) 1, -deriv (deriv u) x ≤ -deriv (deriv v) x)
    (hu0 : u 0 ≤ v 0) (hu1 : u 1 ≤ v 1) :
    ∀ x ∈ Set.Icc (0 : ℝ) 1, u x ≤ v x := by
  -- Apply the concavity result to conclude the proof.
  have h_concave : ConcaveOn ℝ (Set.Icc 0 1) (fun x => v x - u x) := by
    apply_rules [ concaveOn_of_deriv2_nonpos ];
    · exact convex_Icc _ _;
    · exact ContinuousOn.sub ( continuousOn_of_forall_continuousAt fun x hx => HasDerivAt.continuousAt ( hv x ( hJ_sub hx ) ) ) ( continuousOn_of_forall_continuousAt fun x hx => HasDerivAt.continuousAt ( hu x ( hJ_sub hx ) ) );
    · exact fun x hx => DifferentiableAt.differentiableWithinAt ( by exact DifferentiableAt.sub ( hv x ( hJ_sub <| interior_subset hx ) |> HasDerivAt.differentiableAt ) ( hu x ( hJ_sub <| interior_subset hx ) |> HasDerivAt.differentiableAt ) );
    · norm_num +zetaDelta at *;
      exact fun x hx => DifferentiableAt.differentiableWithinAt ( by exact DifferentiableAt.congr_of_eventuallyEq ( show DifferentiableAt ℝ ( fun x => deriv v x - deriv u x ) x from DifferentiableAt.sub ( hv' x ( hJ_sub <| Set.Ioo_subset_Icc_self hx ) ) ( hu' x ( hJ_sub <| Set.Ioo_subset_Icc_self hx ) ) ) <| Filter.eventuallyEq_of_mem ( Ioo_mem_nhds hx.1 hx.2 ) fun y hy => by rw [ show deriv ( fun x => v x - u x ) y = deriv v y - deriv u y from deriv_sub ( hv y ( hJ_sub <| Set.Ioo_subset_Icc_self hy ) ) ( hu y ( hJ_sub <| Set.Ioo_subset_Icc_self hy ) ) ] );
    · simp +zetaDelta at *;
      intro x hx₁ hx₂; rw [ show deriv ( deriv fun x => v x - u x ) x = deriv ( fun x => deriv v x - deriv u x ) x from Filter.EventuallyEq.deriv_eq <| by filter_upwards [ Ioo_mem_nhds hx₁ hx₂ ] with y hy using deriv_sub ( hv y <| hJ_sub <| Set.Ioo_subset_Icc_self hy ) ( hu y <| hJ_sub <| Set.Ioo_subset_Icc_self hy ) ] ;
      norm_num [ hv' x ( hJ_sub ⟨ hx₁.le, hx₂.le ⟩ ), hu' x ( hJ_sub ⟨ hx₁.le, hx₂.le ⟩ ) ] ; linarith [ hineq x hx₁ hx₂ ];
  intro x hx; have := h_concave.2 ( show 0 ∈ Set.Icc 0 1 by norm_num ) ( show 1 ∈ Set.Icc 0 1 by norm_num ) ; simp_all +decide [ ConcaveOn ] ;
  have := @this ( 1 - x ) x ( by linarith ) ( by linarith ) ( by linarith ) ; norm_num at this ; nlinarith;

end Submission

import Mathlib

open SimpleGraph

namespace Submission

set_option maxHeartbeats 800000 in
theorem finite_graph_ramsey_theorem :
    ∀ r s : ℕ, 2 ≤ r → 2 ≤ s → ∃ n : ℕ, ∀ G : SimpleGraph (Fin n), ¬ G.CliqueFree r ∨ ¬ Gᶜ.CliqueFree s := by
  intro r s hr hs;
  by_contra! h;
  -- We proceed by strong induction on $r + s$.
  induction' r using Nat.strong_induction_on with r ih generalizing s;
  induction' s using Nat.strong_induction_on with s ih';
  -- Consider the graph $G$ on $n = n_1 + n_2$ vertices, where $n_1$ and $n_2$ are the witnesses for $r-1$ and $s$, and $r$ and $s-1$ respectively.
  obtain ⟨n1, hn1⟩ : ∃ n1, ∀ G : SimpleGraph (Fin n1), ¬G.CliqueFree (r - 1) ∨ ¬Gᶜ.CliqueFree s := by
    by_cases hr1 : r - 1 ≥ 2;
    · exact not_forall_not.mp fun contra => ih ( r - 1 ) ( Nat.pred_lt ( ne_bot_of_gt hr ) ) s hr1 hs fun n => by aesop;
    · interval_cases _ : r - 1 <;> simp_all +decide;
      exact ⟨ 1, fun G => Or.inl ⟨ 0 ⟩ ⟩
  obtain ⟨n2, hn2⟩ : ∃ n2, ∀ G : SimpleGraph (Fin n2), ¬G.CliqueFree r ∨ ¬Gᶜ.CliqueFree (s - 1) := by
    by_cases hs' : 2 ≤ s - 1;
    · exact not_forall_not.mp fun contra => ih' ( s - 1 ) ( Nat.sub_lt ( by linarith ) ( by linarith ) ) hs' fun n => by push Not at *; tauto;
    · interval_cases _ : s - 1 <;> simp_all +decide;
      exact ⟨ 1, fun G => Or.inr ⟨ 0 ⟩ ⟩
  set n := n1 + n2 + 1 with hn_def;
  obtain ⟨ G, hG₁, hG₂ ⟩ := h n;
  -- Consider the vertex $v$ in $G$ with the maximum degree.
  obtain ⟨v, hv⟩ : ∃ v : Fin n, (G.neighborFinset v).card ≥ n1 ∨ (Gᶜ.neighborFinset v).card ≥ n2 := by
    have h_deg : ∀ v : Fin n, (G.neighborFinset v).card + (Gᶜ.neighborFinset v).card = n - 1 := by
      intro v; rw [ ← Finset.card_union_of_disjoint ];
      · convert Finset.card_erase_of_mem ( Finset.mem_univ v ) using 2 ; ext w ; by_cases hw : G.Adj v w <;> aesop;
        simp +decide [ hn_def ];
      · simp +contextual [ Finset.disjoint_left, SimpleGraph.neighborFinset ];
    exact ⟨ ⟨ 0, Nat.succ_pos _ ⟩, Classical.or_iff_not_imp_left.2 fun h => by linarith [ h_deg ⟨ 0, Nat.succ_pos _ ⟩, Nat.sub_add_cancel ( show 1 ≤ n from Nat.succ_pos _ ) ] ⟩;
  cases' hv with hv hv;
  · -- Let $A$ be the set of neighbors of $v$ in $G$.
    obtain ⟨A, hA⟩ : ∃ A : Finset (Fin n), A ⊆ G.neighborFinset v ∧ A.card = n1 := by
      exact Finset.le_card_iff_exists_subset_card.mp hv;
    -- Consider the subgraph $G[A]$ induced by $A$.
    set GA : SimpleGraph (Fin n1) := SimpleGraph.fromRel (fun i j => G.Adj (A.orderEmbOfFin hA.right i) (A.orderEmbOfFin hA.right j)) with hGA_def;
    cases' hn1 GA with hGA hGA <;> simp_all +decide [ SimpleGraph.CliqueFree ];
    · obtain ⟨ x, hx ⟩ := hGA;
      refine' hG₁ ( Finset.image ( fun i => A.orderEmbOfFin hA.2 i ) x ∪ { v } ) _;
      simp_all +decide [ SimpleGraph.isNClique_iff ];
      refine' ⟨ ⟨ _, _ ⟩, _ ⟩;
      · intro a ha b hb hab; simp_all +decide [ SimpleGraph.isClique_iff, SimpleGraph.fromRel ] ;
        obtain ⟨ i, hi, rfl ⟩ := ha; obtain ⟨ j, hj, rfl ⟩ := hb; specialize hx; have := hx.1 hi hj; simp_all +decide [ SimpleGraph.adj_comm ] ;
      · exact fun i hi hi' => by have := hA.1 ( Finset.orderEmbOfFin_mem A hA.2 i ) ; aesop;
      · rw [ Finset.card_insert_of_notMem ] <;> norm_num [ hx.2 ];
        · rw [ Finset.card_image_of_injective _ fun i j hij => by simpa [ Fin.ext_iff ] using hij, hx.2, Nat.sub_add_cancel ( by linarith ) ];
        · intro i hi; have := hA.1 ( Finset.orderEmbOfFin_mem A hA.2 i ) ; aesop;
    · obtain ⟨ t, ht ⟩ := hGA;
      refine' hG₂ ( Finset.image ( fun i => A.orderEmbOfFin hA.2 i ) t ) _;
      simp_all +decide [ SimpleGraph.isNIndepSet_iff ];
      simp_all +decide [ SimpleGraph.IsIndepSet, Finset.card_image_of_injective, Function.Injective ];
      intro x hx y hy hxy; simp_all +decide [ SimpleGraph.adj_comm ] ;
      obtain ⟨ i, hi, rfl ⟩ := hx; obtain ⟨ j, hj, rfl ⟩ := hy; specialize ht; have := ht.1 hi hj; aesop;
  · -- Consider the subgraph $H$ of $G$ induced by the neighbors of $v$ in $Gᶜ$.
    obtain ⟨H, hH⟩ : ∃ H : Finset (Fin n), H.card = n2 ∧ ∀ u ∈ H, u ≠ v ∧ Gᶜ.Adj u v := by
      obtain ⟨ H, hH ⟩ := Finset.exists_subset_card_eq hv;
      exact ⟨ H, hH.2, fun u hu => ⟨ by rintro rfl; exact absurd ( hH.1 hu ) ( by simp +decide [ SimpleGraph.neighborFinset_def ] ), by simpa [ SimpleGraph.adj_comm ] using hH.1 hu ⟩ ⟩;
    obtain ⟨H', hH'⟩ : ∃ H' : SimpleGraph (Fin n2), (H'.CliqueFree r ∧ H'ᶜ.CliqueFree (s - 1)) := by
      have h_subgraph : ∃ f : Fin n2 → Fin n, Function.Injective f ∧ ∀ i, f i ∈ H := by
        exact ⟨ fun i => H.orderEmbOfFin ( by aesop ) i, by aesop_cat, fun i => by aesop ⟩
      obtain ⟨ f, hf₁, hf₂ ⟩ := h_subgraph;
      use SimpleGraph.comap f G;
      constructor;
      · intro t ht;
        have := hG₁ ( Finset.image f t ) ?_;
        · exact this;
        · simp_all +decide [ SimpleGraph.isNClique_iff, Finset.card_image_of_injective _ hf₁ ];
          intro x hx y hy; aesop;
      · intro t ht;
        have h_clique : (SimpleGraph.comap f G)ᶜ.IsNClique (s - 1) t → Gᶜ.IsNClique (s - 1) (Finset.image f t) := by
          simp +decide [ SimpleGraph.isNClique_iff, Finset.card_image_of_injective _ hf₁ ];
          simp +decide [ SimpleGraph.IsIndepSet, Set.Pairwise ];
          exact fun h₁ h₂ => ⟨ fun x hx y hy hxy => h₁ hx hy ( by simpa [ hf₁.eq_iff ] using hxy ), h₂ ⟩;
        have h_clique : Gᶜ.IsNClique s (Finset.image f t ∪ {v}) := by
          simp_all +decide [ SimpleGraph.isNClique_iff ];
          simp_all +decide [ SimpleGraph.IsIndepSet, Set.Pairwise ];
          exact ⟨ fun x hx hx' => by have := hH.2 ( f x ) ( hf₂ x ) ; tauto, Nat.succ_pred_eq_of_pos ( pos_of_gt hs ) ⟩;
        exact hG₂ _ h_clique;
    cases hn2 H' <;> tauto

end Submission

import Mathlib

namespace Submission

open scoped Topology unitInterval
open Circle

noncomputable section

/-
Strategy: We construct a MulEquiv from FundamentalGroup Circle 1 to Multiplicative ℤ.

The covering map Circle.exp : ℝ → Circle satisfies:
- Circle.exp 0 = 1
- Circle.exp is a covering map (Circle.isCoveringMap_exp)
- Circle.exp t = 1 ↔ ∃ n : ℤ, t = 2 * π * n
- ℝ is simply connected

The winding number map: given a loop γ at 1, lift it to ℝ starting at 0.
The endpoint is 2πn for some n ∈ ℤ. Map γ to n.

This is a group isomorphism.
-/

private abbrev cov := Circle.isCoveringMap_exp

/-
Circle.exp t = 1 iff t is a multiple of 2π
-/
private lemma circle_exp_eq_one_iff (t : ℝ) :
    Circle.exp t = 1 ↔ ∃ n : ℤ, t = 2 * Real.pi * n := by
  grind +suggestions

-- Extract integer from fiber element
private noncomputable def fiberToInt (t : ℝ) (ht : Circle.exp t = 1) : ℤ :=
  ((circle_exp_eq_one_iff t).mp ht).choose

private lemma fiberToInt_spec (t : ℝ) (ht : Circle.exp t = 1) :
    t = 2 * Real.pi * (fiberToInt t ht : ℝ) :=
  ((circle_exp_eq_one_iff t).mp ht).choose_spec

-- Integer maps back to fiber
private lemma int_to_fiber (n : ℤ) : Circle.exp (2 * Real.pi * n) = 1 :=
  (circle_exp_eq_one_iff _).mpr ⟨n, rfl⟩

/-
fiberToInt is injective (since 2π ≠ 0)
-/
private lemma fiberToInt_injective (t₁ t₂ : ℝ) (h₁ : Circle.exp t₁ = 1)
    (h₂ : Circle.exp t₂ = 1) (heq : fiberToInt t₁ h₁ = fiberToInt t₂ h₂) : t₁ = t₂ := by
  rw [ fiberToInt_spec t₁ h₁, fiberToInt_spec t₂ h₂, heq ]

/-
fiberToInt is additive: if Circle.exp(t₁ + t₂) = 1 with t₁, t₂ in fiber,
then fiberToInt(t₁ + t₂) = fiberToInt(t₁) + fiberToInt(t₂)
-/
private lemma fiberToInt_add (t₁ t₂ : ℝ) (h₁ : Circle.exp t₁ = 1)
    (h₂ : Circle.exp t₂ = 1) :
    fiberToInt (t₁ + t₂) (by rw [Circle.exp_add, h₁, h₂, one_mul]) =
    fiberToInt t₁ h₁ + fiberToInt t₂ h₂ := by
  -- From fiberToInt_spec, t₁ = 2π * n₁ and t₂ = 2π * n₂, so t₁ + t₂ = 2π * (n₁ + n₂).
  have h3 : t₁ + t₂ = 2 * Real.pi * (fiberToInt t₁ h₁ + fiberToInt t₂ h₂) := by
    linarith [ fiberToInt_spec t₁ h₁, fiberToInt_spec t₂ h₂ ];
  -- By uniqueness (fiberToInt_injective), fiberToInt(t₁ + t₂) = n₁ + n₂.
  apply Eq.symm;
  apply Eq.symm; exact (by
    have := fiberToInt_spec (t₁ + t₂) (by
    convert int_to_fiber ( fiberToInt t₁ h₁ + fiberToInt t₂ h₂ ) using 1 ; push_cast [ h3 ] ; ring)
    all_goals generalize_proofs at *;
    exact_mod_cast ( mul_left_cancel₀ ( by positivity : ( 2 * Real.pi : ℝ ) ≠ 0 ) <| by linarith : ( fiberToInt ( t₁ + t₂ ) ‹_› : ℝ ) = fiberToInt t₁ h₁ + fiberToInt t₂ h₂ ))

-- The lift endpoint for a loop
private noncomputable def liftEnd (γ : Path (1 : Circle) 1) : ℝ :=
  cov.liftPath γ.toContinuousMap 0 (by simp [γ.source]) 1

/-
The lift endpoint is in the fiber
-/
private lemma liftEnd_fiber (γ : Path (1 : Circle) 1) :
    Circle.exp (liftEnd γ) = 1 := by
  have := cov.liftPath_lifts γ.toContinuousMap 0 ( by simp +decide [ γ.source ] );
  simpa using congr_fun this 1

/-
Homotopic loops have the same lift endpoint
-/
private lemma liftEnd_homotopic (γ₁ γ₂ : Path (1 : Circle) 1)
    (h : Path.Homotopic γ₁ γ₂) : liftEnd γ₁ = liftEnd γ₂ := by
  apply_rules [ IsCoveringMap.liftPath_apply_one_eq_of_homotopicRel ]

/-
The lift endpoint of the constant loop is 0
-/
private lemma liftEnd_refl : liftEnd (Path.refl 1) = 0 := by
  -- The constant loop at 1 lifts to the constant path at 0 in ℝ.
  have h_const_lift : (cov.liftPath (Path.refl 1).toContinuousMap 0 (by simp)) = ContinuousMap.const _ 0 := by
    have : ((Path.refl 1).toContinuousMap : C(I, Circle)) = ContinuousMap.const _ 1 := by
      aesop
    grind +suggestions;
  exact congr_arg ( fun f => f 1 ) h_const_lift

/-
Key helper: the lift of a path starting at c (in the kernel of exp) equals
the lift starting at 0 plus c.
This uses: exp(x + c) = exp(x) when exp(c) = 1.
-/
private lemma liftPath_translate (γ : C(I, Circle)) (c : ℝ) (hc : Circle.exp c = 1)
    (h0 : γ 0 = Circle.exp 0) (hc' : γ 0 = Circle.exp c) :
    cov.liftPath γ c hc' =
    (ContinuousMap.mk (fun t => cov.liftPath γ 0 h0 t + c) (by fun_prop)) := by
  apply ContinuousMap.ext
  intro t
  simp [cov] at *;
  have h_liftPath_eq : ∀ t : I, Circle.exp ((cov.liftPath γ 0 h0) t + c) = γ t := by
    intro t; have := IsCoveringMap.liftPath_lifts cov γ 0 h0; simp_all +decide [ Circle.exp_add ] ;
    exact congr_fun this t;
  have h_liftPath_eq : cov.liftPath γ c hc' = ContinuousMap.mk (fun t => (cov.liftPath γ 0 h0) t + c) (by
  exact Continuous.add ( by exact? ) continuous_const) := by
    have h_liftPath_eq : Circle.exp ∘ (ContinuousMap.mk (fun t => (cov.liftPath γ 0 h0) t + c) (by
    exact Continuous.add ( by exact? ) continuous_const)) = γ := by
      exact funext h_liftPath_eq
    grind +suggestions;
  exact congr_arg ( fun f => f t ) h_liftPath_eq

/-
The lift endpoint is additive under path composition
Note: in FundamentalGroup, mul(a,b) = b ≫ a = b.trans a as paths
So liftEnd(a.trans b) = liftEnd(a) + liftEnd(b)
-/
private lemma liftEnd_trans (γ₁ γ₂ : Path (1 : Circle) 1) :
    liftEnd (γ₁.trans γ₂) = liftEnd γ₁ + liftEnd γ₂ := by
  rw [ add_comm ];
  -- By definition of monodromy, we have:
  have h_monodromy : (cov.liftPath (γ₁.trans γ₂).toContinuousMap 0 (by simp [γ₁.source]) 1) = (cov.liftPath γ₂.toContinuousMap (cov.liftPath γ₁.toContinuousMap 0 (by simp [γ₁.source]) 1) (by
  simp +decide [ γ₂.source ];
  exact Eq.symm ( liftEnd_fiber γ₁ )) 1) := by
    have := @IsCoveringMap.monodromy_trans_apply;
    convert congr_arg Subtype.val ( this cov ( Quotient.mk'' γ₁ ) ( Quotient.mk'' γ₂ ) ⟨ 0, by simp +decide [ γ₁.source ] ⟩ ) using 1
  generalize_proofs at *;
  unfold liftEnd at *;
  rw [ h_monodromy, liftPath_translate ];
  all_goals norm_num;
  convert liftEnd_fiber γ₁ using 1

-- The map from loops to integers, well-defined on homotopy classes
private noncomputable def windingNum : FundamentalGroup Circle 1 → ℤ :=
  fun γ => Quotient.lift (fun p => fiberToInt (liftEnd p) (liftEnd_fiber p))
    (fun a b h => by
      have heq := liftEnd_homotopic a b (Path.Homotopic.Quotient.eq.mp (Quotient.sound h))
      simp only [heq]) γ

/-
windingNum is a group homomorphism
FundamentalGroup multiplication: a * b = b ≫ a (in categorical sense)
In terms of paths: a * b corresponds to b.trans(a) in some sense
Actually End mul corresponds to ≫ which is Quotient.comp
-/
private lemma windingNum_one : windingNum 1 = 0 := by
  unfold windingNum;
  erw [ show ( 1 : FundamentalGroup Circle 1 ) = Quotient.mk'' ( Path.refl 1 ) from ?_ ];
  · convert fiberToInt_spec 0 _;
    all_goals norm_num [ Circle.exp_zero ];
    erw [ Quotient.lift_mk ] ; norm_num [ liftEnd_refl ];
  · rfl

private lemma windingNum_mul (a b : FundamentalGroup Circle 1) :
    windingNum (a * b) = windingNum a + windingNum b := by
  induction' a using Quotient.ind with a;
  nontriviality;
  induction' b using Quotient.ind with b;
  -- Apply the lemma that the fiberToInt of a sum is the sum of the fiberToInts.
  have h_fiberToInt : fiberToInt (liftEnd (b.trans a)) (liftEnd_fiber (b.trans a)) = fiberToInt (liftEnd b) (liftEnd_fiber b) + fiberToInt (liftEnd a) (liftEnd_fiber a) := by
    grind +suggestions;
  convert h_fiberToInt using 1;
  exact add_comm _ _

/-
windingNum is injective (uses simply-connectedness of ℝ)
-/
set_option maxHeartbeats 800000 in
private lemma windingNum_injective : Function.Injective windingNum := by
  intro a b hab
  obtain ⟨p_a, hp_a⟩ := Quotient.exists_rep a
  obtain ⟨p_b, hp_b⟩ := Quotient.exists_rep b
  have h_lift : liftEnd p_a = liftEnd p_b := by
    exact fiberToInt_injective _ _ ( liftEnd_fiber p_a ) ( liftEnd_fiber p_b ) <| by aesop;
  have h_homotopic : Path.Homotopic p_a p_b := by
    -- Since the lifts of p_a and p_b are homotopic, we can project this homotopy down to the circle.
    have h_homotopic : ContinuousMap.HomotopyRel (cov.liftPath p_a.toContinuousMap 0 (by simp [p_a.source]) : C(I, ℝ)) (cov.liftPath p_b.toContinuousMap 0 (by simp [p_b.source]) : C(I, ℝ)) {0, 1} := by
      have h_lift_homotopic : ∀ (p q : C(I, ℝ)), p 0 = q 0 → p 1 = q 1 → ContinuousMap.HomotopyRel p q {0, 1} := by
        intro p q hp hq;
        refine' ⟨ _, _ ⟩;
        refine' ⟨ _, _, _ ⟩;
        exact ⟨ fun ( t, x ) => ( 1 - t.val ) * p x + t.val * q x, by continuity ⟩;
        all_goals norm_num;
        exact fun a ha₁ ha₂ => ⟨ by rw [ hp ] ; ring, by rw [ hq ] ; ring ⟩;
      apply h_lift_homotopic;
      · simp +decide [ IsCoveringMap.liftPath ];
        grind +splitIndPred;
      · exact h_lift;
    constructor;
    constructor;
    swap;
    constructor;
    rotate_left;
    rotate_left;
    exact ContinuousMap.mk ( fun x => Circle.exp ( h_homotopic.toContinuousMap x ) ) ( by fun_prop );
    all_goals simp_all +decide [ ContinuousMap.HomotopyRel ];
    · -- Since h_homotopic is a homotopy between the lifts of p_a and p_b, and the lifts start at 0 and end at the same point, the exponential of the homotopy at these points should be 1.
      intros a ha hb
      have h_start : h_homotopic (⟨a, ha, hb⟩, 0) = 0 := by
        grind +suggestions
      have h_end : h_homotopic (⟨a, ha, hb⟩, 1) = liftEnd p_a := by
        have := h_homotopic.2; aesop;
      simp [h_start, h_end, Circle.exp_zero, Circle.exp_add];
      exact liftEnd_fiber p_a;
    · intro a ha hb; exact (by
      convert congr_arg ( fun x => x ⟨ a, ha, hb ⟩ ) ( cov.liftPath_lifts p_a.toContinuousMap 0 ( by simp +decide [ p_a.source ] ) ) using 1);
    · intro a ha hb; exact (by
      convert congr_arg ( fun x => x ⟨ a, ha, hb ⟩ ) ( IsCoveringMap.liftPath_lifts ( Circle.isCoveringMap_exp ) p_b.toContinuousMap 0 _ ) using 1)
  have h_eq : a = b := by
    exact hp_a.symm.trans ( Quotient.sound h_homotopic ) |> Eq.trans <| hp_b
  exact h_eq

/-
windingNum is surjective (construct explicit loops)
-/
set_option maxHeartbeats 800000 in
private lemma windingNum_surjective : Function.Surjective windingNum := by
  -- For any integer n, construct the loop γ_n(t) = Circle.exp(2 * π * n * t).
  have h_loop : ∀ n : ℤ, ∃ γ : Path (1 : Circle) 1, liftEnd γ = 2 * Real.pi * n := by
    intro n;
    refine' ⟨ _, _ ⟩;
    refine' ⟨ _, _, _ ⟩;
    exact ⟨ fun t => Circle.exp ( 2 * Real.pi * n * t ), by continuity ⟩;
    all_goals norm_num [ liftEnd ];
    exact int_to_fiber n;
    have := @cov.eq_liftPath_iff';
    specialize @this ⟨ fun t => Circle.exp ( 2 * Real.pi * n * t ), by continuity ⟩ 0 ( by simp +decide [ Circle.exp_zero ] ) ⟨ fun t => 2 * Real.pi * n * t, by continuity ⟩ ; norm_num at this;
    exact congr_arg ( fun f => f 1 ) ( this.mpr rfl ) ▸ by norm_num;
  -- For any integer n, construct the loop γ_n(t) = Circle.exp(2 * π * n * t) and show that its winding number is n.
  intro n
  obtain ⟨γ, hγ⟩ := h_loop n
  use Quotient.mk'' γ
  simp [windingNum, hγ];
  have := fiberToInt_spec ( liftEnd γ ) ( liftEnd_fiber γ );
  exact_mod_cast ( by nlinarith [ Real.pi_pos ] : ( fiberToInt ( liftEnd γ ) ( liftEnd_fiber γ ) : ℝ ) = n )

-- Package as MonoidHom
private noncomputable def windingNumHom : FundamentalGroup Circle 1 →* Multiplicative ℤ where
  toFun γ := Multiplicative.ofAdd (windingNum γ)
  map_one' := by simp [windingNum_one]
  map_mul' a b := by simp [windingNum_mul]

-- Package as MulEquiv
private noncomputable def windingNumEquiv :
    FundamentalGroup Circle 1 ≃* Multiplicative ℤ :=
  MulEquiv.ofBijective windingNumHom ⟨by
    intro a b h
    simp [windingNumHom] at h
    exact windingNum_injective h, by
    intro x
    obtain ⟨a, ha⟩ := windingNum_surjective x.toAdd
    exact ⟨a, by simp [windingNumHom, ha]⟩⟩

/-
The pi1 ≃* FundamentalGroup equivalence
-/
set_option maxHeartbeats 800000 in
private noncomputable def pi1MulEquivFG :
    π_ 1 Circle (1 : Circle) ≃* FundamentalGroup Circle (1 : Circle) := by
  refine MulEquiv.mk HomotopyGroup.pi1EquivFundamentalGroup ?_
  intro a b
  show HomotopyGroup.pi1EquivFundamentalGroup (a * b) =
    HomotopyGroup.pi1EquivFundamentalGroup a * HomotopyGroup.pi1EquivFundamentalGroup b
  obtain ⟨ a, ha ⟩ := a;
  induction b using Quotient.inductionOn';
  rename_i b;
  obtain ⟨ b, hb ⟩ := b;
  erw [ Quotient.eq' ];
  refine' ⟨ _, _ ⟩;
  refine' ⟨ _, _, _ ⟩;
  refine' ⟨ fun p => if p.1 = 0 then ( genLoopEquivOfUnique ( Fin 1 ) ) ( ( GenLoop.loopHomeo ( Classical.arbitrary ( Fin 1 ) ) ).symm ( ( ( GenLoop.loopHomeo ( Classical.arbitrary ( Fin 1 ) ) ).toEquiv ⟨ b, hb ⟩ ).trans ( ( GenLoop.loopHomeo ( Classical.arbitrary ( Fin 1 ) ) ).toEquiv ⟨ a, ha ⟩ ) ) ) p.2 else ( ( genLoopEquivOfUnique ( Fin 1 ) ) ⟨ b, hb ⟩ ).trans ( ( genLoopEquivOfUnique ( Fin 1 ) ) ⟨ a, ha ⟩ ) p.2, _ ⟩;
  all_goals simp +decide [ genLoopEquivOfUnique ];
  · refine' Continuous.if _ _ _;
    · simp +decide [ frontier_eq_closure_inter_closure ];
      simp +decide [ mem_closure_iff_seq_limit, mem_interior_iff_mem_nhds, nhds_prod_eq ];
      intro a_1 hp hq a_2 hp_1 hq_1 x hx hx' hx''; contrapose! hx''; simp_all +decide [ Filter.mem_prod_iff ] ;
      simp_all +decide [ GenLoop.fromLoop, GenLoop.toLoop ];
      simp_all +decide [ Path.trans_apply ];
      split_ifs at hx'' <;> simp_all +decide [ Cube.insertAt ];
      · simp_all +decide [ Homeomorph.funSplitAt ];
        simp_all +decide [ Homeomorph.piSplitAt ];
        simp_all +decide [ Equiv.piSplitAt ];
        simp_all +decide [ Fin.eq_zero ];
      · simp_all +decide [ Homeomorph.funSplitAt ];
        simp_all +decide [ Homeomorph.piSplitAt ];
        simp_all +decide [ Equiv.piSplitAt ];
        simp_all +decide [ Fin.eq_zero ];
    · fun_prop;
    · fun_prop;
  · simp +decide [ GenLoop.fromLoop, GenLoop.toLoop, GenLoop.const ]
    aesop

-- Main theorem
theorem pi1_circle_mulEquiv_int :
    Nonempty (HomotopyGroup.Pi 1 Circle (1 : Circle) ≃* Multiplicative ℤ) :=
  ⟨pi1MulEquivFG.trans windingNumEquiv⟩

end

