  obtain ⟨d, hd⟩ : ∃ d ∈ Set.Ioo a b, y₂ d = 0 ∧ d ≠ c := by
    exact not_forall_not.mp fun h => h_unique_contra ⟨ c, hc, fun x hx => Classical.not_not.mp fun hx' => h x <| by aesop ⟩;
